import{_ as t,m as b,c as e,b as c}from"./index-Bj0FLdMW.js";const s={},d={class:"hc-container policy-page"};function o(f,a){return b(),e("div",d,[...a[0]||(a[0]=[c('<article class="hc-card content" data-v-81fb7b38><h1 data-v-81fb7b38>鸿创工作室社区规范</h1><p class="lead" data-v-81fb7b38>这里是面向 Minecraft、AI、资源创作和技术交流的社区。为了保证讨论质量和资源安全，请遵守以下规则。</p><section data-v-81fb7b38><h2 data-v-81fb7b38>一、鼓励的内容</h2><p data-v-81fb7b38>欢迎发布原创教程、插件资源、服务器经验、贴图模型、玩法讨论、更新日志、技术问题、作品展示和有价值的经验总结。提问时尽量附上版本号、报错信息、复现步骤和截图，方便他人帮助你。</p></section><section data-v-81fb7b38><h2 data-v-81fb7b38>二、禁止的内容</h2><p data-v-81fb7b38>禁止发布违法违规、政治极端、色情低俗、血腥恐怖、赌博诈骗、木马病毒、外挂作弊、刷量脚本、恶意引流、盗号内容、侵权盗版资源、未授权搬运、钓鱼链接、人身攻击、引战辱骂和垃圾广告。</p></section><section data-v-81fb7b38><h2 data-v-81fb7b38>三、资源发布要求</h2><p data-v-81fb7b38>资源标题、简介、封面、版本号、支持版本、更新日志和下载地址应真实、清晰、可验证。若资源存在付费前置、外部依赖、兼容限制、使用协议或二次转载要求，请在页面中写明。禁止用失效链接、空文件、诱导跳转或与内容不符的宣传误导用户。</p></section><section data-v-81fb7b38><h2 data-v-81fb7b38>四、互动礼仪</h2><p data-v-81fb7b38>讨论中请尽量对事不对人，尊重不同技术路线和创作风格。可以指出问题，但不要持续骚扰、群嘲、阴阳怪气、恶意挂人或进行私信轰炸。对新人提问和基础问题，建议保持耐心。</p></section><section data-v-81fb7b38><h2 data-v-81fb7b38>五、审核与处罚</h2><p data-v-81fb7b38>平台会结合人工和系统规则对内容进行审核。对违规内容，平台可采取删除、驳回、下架、屏蔽、限制互动、禁言、封禁账号、取消推荐等措施。对严重侵权、恶意传播危险文件或多次违规行为，平台可能直接升级处罚并保留证据。</p></section><section data-v-81fb7b38><h2 data-v-81fb7b38>六、举报建议</h2><p data-v-81fb7b38>发现问题时，优先使用平台举报入口并提供资源链接、帖子地址、截图和简要说明。重复举报、恶意举报或捏造事实同样会影响账号信用。</p></section></article>',1)])])}const i=t(s,[["render",o],["__scopeId","data-v-81fb7b38"]]);export{i as default};
